{"file_path":"/tmp/linkcheck.py","content":"#!/usr/bin/env python3
"""
local_link_check.py —— 最终目录本地链接解析检查（独立于 G4）
检查 outputs/ 下所有 HTML/SVG 引用到的本地 href/src 是否都解析到最终目录内真实存在文件。
- 排除 http/https/mailto/#/data: 等外部或非文件引用。
- 动态计数: 检查数、缺失数、解析数全部由实际扫描产生。
- 有界退出: 缺失=0 -> exit 0, 否则 exit 1。
"""
import os, re, sys

OUT = "<MAINTAINER_LOCAL_PATH>"

# 需检查的 web-serving 文件类型（它们内含 href/src）
TYPES = {".html", ".htm", ".svg"}

def is_external_or_nonfile(u):
    if not u:
        return True
    if u.startswith("#") or u.startswith("http://") or u.startswith("https://"):
        return True
    if u.startswith("mailto:") or u.startswith("data:") or u.startswith("javascript:"):
        return True
    # fragment-only inside same file
    if "#" in u:
        u = u.split("#", 1)[0]
    return False

checked_refs = 0
missing = []
resolved = []
files_scanned = 0

for root, _dirs, files in os.walk(OUT):
    for name in files:
        full = os.path.join(root, name)
        ext = os.path.splitext(name)[1].lower()
        if ext not in TYPES:
            continue
        files_scanned += 1
        try:
            text = open(full, encoding="utf-8").read()
        except Exception as e:
            missing.append("%s (unreadable: %s)" % (os.path.relpath(full, OUT), e))
            continue
        for m in re.finditer(r'(?:href|src|url)\s*\(\s*(["\']?)([^"\')\s]+)\1\s*\)', text):
            u = m.group(2)
            if is_external_or_nonfile(u):
                continue
            checked_refs += 1
            trg = os.path.normpath(os.path.join(os.path.dirname(full), u.split("#", 1)[0]))
            if os.path.exists(trg):
                resolved.append((os.path.relpath(full, OUT), u))
            else:
                missing.append("%s -> %s" % (os.path.relpath(full, OUT), u))
        # 通用 attr 形式 (href="..." src="...")
        for m in re.finditer(r'(?:href|src)\s*=\s*["\']([^"\']+)["\']', text):
            u = m.group(1)
            if is_external_or_nonfile(u):
                continue
            checked_refs += 1
            trg = os.path.normpath(os.path.join(os.path.dirname(full), u.split("#", 1)[0]))
            if os.path.exists(trg):
                resolved.append((os.path.relpath(full, OUT), u))
            else:
                missing.append("%s -> %s" % (os.path.relpath(full, OUT), u))

print("=== local link resolution check (final outputs/) ===")
print("files_scanned = %d (dynamic)" % files_scanned)
print("local refs checked = %d (dynamic)" % checked_refs)
print("resolved = %d  missing = %d" % (len(resolved), len(missing)))
if resolved:
    print("resolved refs:")
    for f, u in sorted(set(resolved)):
        print("  [%s] %s" % (f, u))
if missing:
    print("MISSING (%d):" % len(missing))
    for m in sorted(set(missing)):
        print("  " + m)
print("RESULT: %s" % ("PASS (missing=0, cache excluded)" if len(missing) == 0 else "FAIL"))
sys.exit(0 if len(missing) == 0 else 1)
"}

